code.C:
#include <stdio.h>
#include <string.h>
int is_vowel(char c) {
    return strchr("aeiouAEIOU", c) != NULL;
}
int main() {
    char s[1000]; if (!fgets(s, sizeof(s), stdin)) return 0;
    int len = strlen(s);
    while (len > 0 && (s[len-1] == '\n' || s[len-1] == '\r')) s[--len] = '\0';
    for (int i = 0; i < len; i++) if (!is_vowel(s[i])) putchar(s[i]);
    putchar('\n');
    return 0;
}

code.C++:
#include <iostream>
#include <string>
using namespace std;
bool is_vowel(char c) {
    return string("aeiouAEIOU").find(c) != string::npos;
}
int main() {
    string s; if (!getline(cin, s)) return 0;
    for (char c : s) if (!is_vowel(c)) cout << c;
    cout << "\n";
    return 0;
}

